-- Cases de Sales & Trading (docs/cases: PDF 'Corporate Finance, Sales & Trading e Operações'). Todos os dados são fictícios.

INSERT INTO cases (id, title, area_id, summary, mission, context, content, status, island_order)
VALUES (
  'st-simplificado',
  'Sales & Trading simplificado: dia de payroll na mesa de câmbio',
  'sales-trading',
  'Cote uma exportadora, dimensione a posição da mesa pelo stop e reaja ao payroll americano, em um chat com a chefe da mesa e uma banca de três pessoas.',
  'Escolher o que importa antes de cotar, definir o preço, dimensionar a posição pelo stop, calcular o resultado depois do dado, proteger o sigilo do cliente e explicar suas decisões à banca.',
  $$Sexta-feira. Em poucos minutos sai o payroll americano, o dado de emprego dos Estados Unidos, que costuma mexer forte no dólar. Você é trader júnior da mesa de câmbio da Arquipélago. Uma exportadora de grãos, cliente da mesa, liga: quer vender US$ 5 milhões agora, antes do dado. Marina, head da mesa, acompanha você pelo chat; Eva, sua mentora, ajuda se você travar. No fim, uma banca com Ricardo, Paula e Helena avalia suas decisões. O case tem cinco capítulos curtos e leva cerca de 15 minutos. Empresa e números são fictícios.$$,
  $${"resumo": "Sales & Trading é a mesa de operações de bancos e corretoras: compra e vende ativos para clientes e para o próprio banco e administra o risco dessas posições. Neste case rápido, você é trader júnior da mesa de câmbio da Arquipélago, numa sexta-feira de payroll americano, e precisa cotar um cliente, dimensionar o risco e reagir ao dado. A Arquipélago e os números são fictícios.", "links": [], "cards": [{"titulo": "O que é Sales & Trading", "texto": "É a mesa de operações de bancos e corretoras, onde ativos financeiros (juros, câmbio, ações, crédito privado, derivativos e commodities) são comprados e vendidos para clientes e para o próprio banco. Sales atende clientes institucionais e traz a operação para a mesa; trading dá o preço, executa e administra o risco das posições, dentro de limites.", "naPratica": "Neste case você é trader júnior da mesa de câmbio e precisa cotar um cliente e cuidar do risco da mesa ao mesmo tempo."}, {"titulo": "Bid, ask, spread e market making", "texto": "Bid é o preço em que a mesa compra; ask, o preço em que vende; spread é a diferença entre eles. Muitas vezes a mesa faz market making: oferece compra e venda ao mesmo tempo e ganha na diferença. A liquidez é a facilidade de comprar ou vender sem mexer muito no preço.", "naPratica": "Antes de um dado importante o mercado fica mais volátil, e o spread cobrado normalmente tende a refletir esse risco maior."}, {"titulo": "Posição, P&L e stop", "texto": "A posição mostra o quanto a mesa está comprada (ganha se o preço sobe) ou vendida (ganha se cai). O P&L é o resultado do dia. Os limites de risco definem o tamanho máximo da posição, e o stop, a perda máxima aceita no dia: ao bater o stop, a posição é reduzida.", "naPratica": "Dimensionar a posição pelo stop é perguntar: se o preço andar contra mim, quanto eu perco, e isso cabe no limite?"}, {"titulo": "Dados que mexem no mercado", "texto": "Copom, inflação, payroll americano e decisões do Fed movem os preços. O payroll é o dado de emprego dos Estados Unidos e costuma mexer forte no dólar.", "naPratica": "Na saída de dados importantes há momentos de pico na mesa: a decisão de risco precisa ser tomada antes, e não depois do número."}, {"titulo": "Ética de mesa", "texto": "A mesa guarda sigilo das ordens dos clientes, não usa informação de um cliente para ganhar antes dele (front-running) e registra todas as conversas.", "naPratica": "Se alguém pergunta o que outro cliente fez, a única resposta possível é não informar."}], "comoSeEntra": {"ondeSeTrabalha": "Mesas de operações de bancos e corretoras, em produtos como juros, câmbio, ações, crédito privado, derivativos e commodities.", "formacoes": "A confirmar com uma profissional da área antes de publicar.", "vagas": "Estágio ou posição de analista ou trader júnior em mesas de bancos e corretoras. Quem estagia registra operações (boletas), atualiza planilhas de preço e posição, prepara materiais para clientes e acompanha a mesa.", "oQueAjuda": "Rapidez com números, comunicação objetiva, calma sob pressão, gosto por acompanhar o mercado todo dia, Excel e Python.", "quandoRecrutam": "Vagas fecham rápido: acompanhe as páginas de carreira das empresas e confira de novo antes de se candidatar. Certificações do PQO da B3 e da ANBIMA são pedidas em algumas funções."}}$$::jsonb,
  'publicado',
  11
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO contents (id, title, type, area_id, summary, body, url, minutes, case_ids) VALUES
($$st-simplificado-bid-ask$$, $$Bid, ask, spread e liquidez$$, $$glossario$$, 'sales-trading', $$Como a mesa forma o preço de compra e de venda e por que o spread muda com o risco.$$, $$**Bid** é o preço em que a mesa compra; **ask** é o preço em que vende; o **spread** é a diferença entre eles. Quem faz **market making** oferece compra e venda ao mesmo tempo e ganha na diferença, administrando o estoque de risco que fica na mesa. O spread tende a subir quando a **liquidez** cai (é mais difícil comprar ou vender sem mexer no preço) e quando a **volatilidade** aumenta, como antes de um dado importante. Quanto maior o spread cobrado do cliente, maior o ganho por operação, mas também maior o risco de o cliente procurar outra mesa. Por isso o preço combina três coisas: o risco do momento, a necessidade do cliente e a relação de longo prazo com ele. Para estimar o ganho de spread de uma operação, multiplique a diferença entre o preço médio e o preço cotado pelo tamanho da operação. Exemplo ilustrativo: um spread de R$ 0,01 em US$ 1 milhão rende R$ 10 mil.$$, NULL, 5, $$["st-simplificado"]$$::jsonb),
($$st-simplificado-posicao-stop$$, $$Posição, P&L, limite e stop$$, $$artigo$$, 'sales-trading', $$Como medir quanto uma posição pode perder e como o stop define o tamanho que cabe na mesa.$$, $$A **posição** diz se a mesa está comprada (ganha se o preço sobe) ou vendida (ganha se cai) e em que tamanho. O **P&L** (profit and loss) é o ganho ou a perda das posições no dia. O **limite de posição** é o tamanho máximo permitido; o **stop diário** é a perda máxima aceita no dia, e ao bater o stop a posição é reduzida. Para medir o risco, multiplique o tamanho da posição pela variação possível do preço: uma posição comprada em US$ 2 milhões perde R$ 200 mil se o dólar cair R$ 0,10 (exemplo ilustrativo). Para dimensionar pelo stop, faça a conta ao contrário: divida a perda máxima aceita pela perda por unidade da posição. Respeitar o limite de posição não basta: a posição pode caber no limite e ainda assim perder mais do que o stop num movimento forte. Ao avaliar uma decisão, separe **processo** de **sorte**: ganhar mais mantendo uma posição grande não torna a decisão certa, e uma perda dentro do stop pode ter sido uma boa decisão.$$, NULL, 6, $$["st-simplificado"]$$::jsonb),
($$st-simplificado-dados-etica$$, $$Dados de mercado e ética de mesa$$, $$artigo$$, 'sales-trading', $$O que mexe nos preços no dia e quais regras protegem os clientes.$$, $$Alguns dados movem o mercado: a decisão do **Copom** e a **inflação** no Brasil, o **payroll** americano (dado de emprego dos Estados Unidos) e as decisões do **Fed**. Emprego forte pode subir os juros americanos e fortalecer o dólar, pressionando o real. O calendário econômico, disponível nos portais de mercado, mostra quando cada dado sai. Na mesa vale a **ética**: as ordens dos clientes são sigilosas; é proibido usar a informação de um cliente para ganhar antes dele (**front-running**); e todas as conversas são registradas. Se um cliente pergunta o que outro fez, a resposta é não informar, mesmo que dar uma pista pareça inofensivo. Contar ou insinuar a operação de outro cliente quebra a confiança e é conduta inadequada.$$, NULL, 6, $$["st-simplificado"]$$::jsonb)
ON CONFLICT (id) DO NOTHING;

