INSERT INTO cases (id, title, area_id, summary, mission, context, content, status, island_order)
VALUES (
  'st-complexo',
  'Sales & Trading completo: o livro de juros',
  'sales-trading',
  'Meça o risco de um livro de títulos prefixados, monte o hedge no DI futuro, teste cenários para o Copom e recomende o que fazer, incluindo um fluxo de cliente.',
  'Medir o risco do livro, calcular o hedge para trazer o DV01 ao limite, testar três cenários de juros, verificar o stop, propor a taxa para um cliente e recomendar à head da mesa o que fazer antes do Copom.',
  $$Você trabalha como estagiária na mesa de renda fixa da Arquipélago. O trader responsável pelo livro de títulos prefixados saiu de férias e a head da mesa, Marina, pediu sua ajuda: o livro está acima do limite de risco, o Copom decide amanhã e um cliente quer negociar. Sua missão é medir o risco do livro, montar o hedge, testar cenários e recomendar o que fazer. Os valores são fictícios. Considere aproximações lineares: sem convexidade, sem carregamento e sem custos de corretagem.$$,
  $${"resumo": "Na mesa de renda fixa, o risco de um livro de títulos prefixados é medido pelo DV01 e controlado por limites e por hedge no DI futuro. Neste case, você mede o risco do livro de juros da Arquipélago, monta o hedge, testa cenários para a decisão do Copom, atende um cliente e escreve um memorando para a head da mesa. A Arquipélago e os números são fictícios.", "links": [], "cards": [{"titulo": "Preço e taxa de um título prefixado", "texto": "Num título prefixado, o fluxo de pagamentos é fixo. Quando a taxa de mercado sobe, esse fluxo vale menos hoje e o preço cai; quando a taxa cai, o preço sobe. A relação é inversa.", "naPratica": "Um livro comprado em prefixados ganha se as taxas caem e perde se sobem."}, {"titulo": "Duration e DV01", "texto": "A duration mede a sensibilidade do preço aos juros. O DV01 diz quanto a posição ganha ou perde para cada 0,01 ponto percentual (1 ponto-base) de mudança na taxa.", "naPratica": "Com o DV01 de cada título, a perda esperada para uma alta de taxa é uma conta simples: DV01 x variação em pontos-base."}, {"titulo": "DI futuro e hedge", "texto": "O DI futuro, negociado na B3, é um contrato sobre a taxa média de juros até uma data. Serve para posicionamento e para hedge. Estar tomado em taxa ganha com alta de juros; estar dado ganha com queda. Hedge é uma operação que reduz um risco que a pessoa já tem.", "naPratica": "Para se proteger de uma alta de juros, a mesa fica tomada em taxa no DI futuro; o número de contratos depende do DV01 de cada contrato."}, {"titulo": "Curva de juros e cenários", "texto": "A curva de juros mostra as taxas esperadas para cada prazo, e as taxas de prazos diferentes podem se mexer de formas diferentes: sobem em paralelo, ficam mais inclinadas (longas sobem mais) ou mais achatadas (curtas sobem mais).", "naPratica": "Um hedge que funciona bem num movimento paralelo pode proteger menos quando só uma parte da curva se mexe, por isso a mesa testa cenários."}, {"titulo": "Limites, stop e conduta", "texto": "A mesa opera dentro de limites de risco (como um DV01 máximo), de um stop diário e de um limite de perda no mês. A ética exige sigilo das ordens dos clientes e proíbe o front-running; as conversas são registradas.", "naPratica": "O risco do livro, o hedge e as conversas com clientes têm de respeitar esses limites e essas regras ao mesmo tempo."}], "comoSeEntra": {"ondeSeTrabalha": "Mesas de operações de bancos e corretoras, em produtos como juros, câmbio, ações, crédito privado, derivativos e commodities.", "formacoes": "A confirmar com uma profissional da área antes de publicar.", "vagas": "Estágio ou posição de analista ou trader júnior em mesas de bancos e corretoras. Quem estagia registra operações (boletas), atualiza planilhas de preço e posição, prepara materiais para clientes e acompanha a mesa.", "oQueAjuda": "Rapidez com números, comunicação objetiva, calma sob pressão, gosto por acompanhar o mercado todo dia, Excel e Python.", "quandoRecrutam": "Vagas fecham rápido: acompanhe as páginas de carreira das empresas e confira de novo antes de se candidatar. Certificações do PQO da B3 e da ANBIMA são pedidas em algumas funções."}}$$::jsonb,
  'publicado',
  12
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO contents (id, title, type, area_id, summary, body, url, minutes, case_ids) VALUES
($$st-complexo-juros-dv01$$, $$Preço, taxa, duration e DV01$$, $$artigo$$, 'sales-trading', $$Por que o preço cai quando a taxa sobe e como o DV01 transforma isso numa conta.$$, $$Num título **prefixado**, o fluxo que ele paga é conhecido desde o início. Se a taxa de mercado sobe, esse fluxo vale menos hoje: o preço cai. A relação entre preço e taxa é inversa. A **duration** mede a sensibilidade do preço aos juros, e o **DV01** traduz essa sensibilidade em reais: é o ganho ou a perda para cada 0,01 ponto percentual (1 ponto-base, ou 1 bp) de mudança na taxa. Com o DV01, a perda de uma posição comprada que sofre uma alta de taxa é, em aproximação linear, **DV01 x número de pontos-base**. Exemplo ilustrativo: um título com DV01 de R$ 2.000 perde cerca de R$ 20 mil se a taxa subir 10 bps. Os DV01 de títulos diferentes somam-se: o DV01 de um livro é a soma dos DV01 das posições. Lembre que a aproximação linear ignora a convexidade; para movimentos pequenos ela é boa, e neste case ela é a regra. Uma posição comprada em prefixados ganha se as taxas caem e perde se sobem. Um **livro** é o conjunto de posições de risco de um trader ou de uma mesa, com limites próprios.$$, NULL, 7, $$["st-complexo"]$$::jsonb),
($$st-complexo-di-hedge$$, $$DI futuro, tomado e dado, e como fazer um hedge$$, $$artigo$$, 'sales-trading', $$Como usar o DI futuro para reduzir o risco de juros de um livro de prefixados.$$, $$O **DI futuro**, negociado na B3, é um contrato sobre a taxa média de juros (a taxa DI) até um vencimento. Ele serve para **posicionamento** (apostar numa direção dos juros) e para **hedge** (reduzir um risco que a pessoa já tem). Estar **tomado** em taxa significa ganhar quando a taxa sobe; estar **dado** significa ganhar quando ela cai. Um livro comprado em prefixados perde com a alta dos juros; para se proteger, a mesa fica tomada no DI futuro. Cada contrato tem um **DV01 por contrato**, que depende do vencimento. Para saber quantos contratos usar, divida o DV01 que se quer cortar pelo DV01 de um contrato: **contratos = DV01 a reduzir ÷ DV01 por contrato**. Exemplo ilustrativo: para cortar R$ 3.000 de DV01 com contratos de R$ 15 cada, são necessários 200 contratos. Há mais de uma forma de montar o hedge: concentrar tudo num vencimento ou dividir entre os vencimentos em que o risco está. Como os vencimentos curtos e longos podem se mexer de formas diferentes, vale comparar as formas em mais de um cenário.$$, NULL, 7, $$["st-complexo"]$$::jsonb),
($$st-complexo-cenarios-limites$$, $$Cenários de curva, limites e stop$$, $$artigo$$, 'sales-trading', $$Como testar um livro em cenários e como o stop define o DV01 máximo.$$, $$A **curva de juros** mostra as taxas esperadas para cada prazo. Ela pode se mexer de formas diferentes: uma **alta paralela** (todas as taxas sobem o mesmo tanto), uma **inclinação** (as taxas longas sobem mais que as curtas) ou um **achatamento** (as curtas sobem mais que as longas). Para testar um livro num cenário, aplique a variação de cada vencimento ao DV01 correspondente e some: **resultado = soma de (DV01 do vencimento x variação em bps)**, com sinal negativo para perda. Compare o resultado sem hedge e com cada forma de hedge. Além do DV01 máximo, a mesa tem um **stop diário** (perda máxima no dia) e um **limite de perda no mês**, do qual parte pode já ter sido usada. Para saber o DV01 máximo que respeita o stop num cenário, divida o stop pela variação em bps: com um stop de R$ 100 mil e uma alta paralela de 25 bps, o DV01 precisa ficar em até R$ 4.000 (exemplo ilustrativo). Quando um cliente compra um título que a mesa tem em carteira, a mesa vende posição de risco e reduz o DV01 do livro: é um hedge natural, e o ganho do spread vem da diferença de taxa entre a venda ao cliente e a taxa média de mercado (1 bp de diferença vale o DV01 vendido, em reais). Na conduta, vale o **sigilo** das operações dos clientes: nunca revele quem compra ou vende. O front-running é proibido e as conversas são registradas.$$, NULL, 7, $$["st-complexo"]$$::jsonb),
($$st-complexo-referencias$$, $$Livros, páginas e acompanhamento diário do mercado$$, $$artigo$$, 'sales-trading', $$Onde estudar derivativos, juros e câmbio e como treinar o raciocínio do case.$$, $$Para os conceitos e o case:

- Livro **"Opções, Futuros e Outros Derivativos"** (John Hull): a referência para derivativos, hedge e risco.
- Livro **"Mercado Financeiro"** (Alexandre Assaf Neto): renda fixa, juros e câmbio no contexto brasileiro.
- Páginas da **B3** sobre o DI futuro e o dólar futuro: como os contratos funcionam e como são negociados.
- **Banco Central**: boletim Focus (expectativas), atas do Copom e a taxa PTAX do dólar.
- **Calendário econômico** (em portais de mercado): saber quando saem Copom, IPCA, payroll e decisões do Fed.
- **Planilha de prática**: monte um livro fictício com três títulos e calcule DV01 e cenários, como no case avançado.

Para a carreira:

- **Programa de Qualificação Operacional (PQO) da B3**: as certificações para quem opera na bolsa.
- **Certificações da ANBIMA**: pedidas em algumas funções comerciais.
- Livro **"Liar's Poker"** (Michael Lewis, em inglês): um retrato, com humor, da cultura das mesas nos anos 1980; bom para conversar sobre o que mudou desde então.
- Acompanhe o mercado todo dia e escolha um ativo (por exemplo, o dólar) para explicar o que o moveu: é a pergunta mais comum em entrevista.

Regras, prazos e certificações devem ser conferidos com a instituição.$$, NULL, 8, $$["st-simplificado", "st-complexo"]$$::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO checkpoints (id, case_id, "order", stage, title, description, points, task_ids) VALUES
($$st-cpc-1$$, 'st-complexo', 1, $$entenda$$, $$Risco de juros, DV01 e hedge$$, $$Entenda como o risco de um livro de prefixados é medido e controlado antes de analisar o livro da Arquipélago.$$, 15, $$[]$$::jsonb),
