($$st-cpc-3$$, 'st-complexo', 3, $$situacao$$, $$Risco atual do livro$$, $$Explique por que o livro perde com a alta de taxa e calcule a perda com 0,25 ponto, comparando com o stop.$$, 30, $$["st-ctask-risco"]$$::jsonb),
($$st-cpc-4$$, 'st-complexo', 4, $$situacao$$, $$Hedge para o limite$$, $$Calcule quantos contratos de DI futuro levam o DV01 ao limite, em duas formas de hedge.$$, 35, $$["st-ctask-hedge"]$$::jsonb),
($$st-cpc-5$$, 'st-complexo', 5, $$situacao$$, $$Cenários do Copom$$, $$Calcule o resultado do livro nos cenários A, B e C, sem hedge e com as duas formas de hedge.$$, 40, $$["st-ctask-cenarios"]$$::jsonb),
($$st-cpc-6$$, 'st-complexo', 6, $$situacao$$, $$O stop e o hedge$$, $$Verifique se o hedge respeita o stop no cenário A e calcule o DV01 máximo e os contratos adicionais.$$, 30, $$["st-ctask-stop"]$$::jsonb),
($$st-cpc-7$$, 'st-complexo', 7, $$situacao$$, $$Fluxo do cliente$$, $$Proponha a taxa de venda ao fundo, calcule o spread e explique o efeito no risco do livro.$$, 35, $$["st-ctask-cliente"]$$::jsonb),
($$st-cpc-8$$, 'st-complexo', 8, $$situacao$$, $$Conduta$$, $$Responda a um cliente que pergunta quem está vendendo jan/2030 hoje.$$, 20, $$["st-ctask-conduta"]$$::jsonb),
($$st-cpc-9$$, 'st-complexo', 9, $$defesa$$, $$Memorando para a head da mesa$$, $$Recomende o que fazer antes do Copom, com números, e uma posição sobre o fluxo do cliente.$$, 40, $$["st-ctask-memorando"]$$::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO tasks (id, case_id, checkpoint_id, title, prompt, fields, support_data, answer_key) VALUES
($$st-task-importa$$, 'st-simplificado', $$st-cp-3$$, $$O que importa antes de cotar$$,
  $$Sexta-feira. Em poucos minutos sai o payroll americano, o dado de emprego dos Estados Unidos, que costuma mexer forte no dólar. Você é trader júnior da mesa de câmbio da Arquipélago.
Uma exportadora de grãos, cliente da mesa, liga: quer vender US$ 5 milhões agora, antes do dado.
[[continuar]]
Marina: “O cliente está na linha. Antes de cotar, o que você precisa olhar?”
[[continuar]]
[[campos: info_1, info_2, info_3]]
Abra os cards de informação abaixo e escolha as três mais importantes para decidir agora, três opções diferentes. Elas só serão comentadas depois da sua escolha.$$,
  $$[{"id": "info_1", "tipo": "opcao", "rotulo": "Primeira informação mais importante", "obrigatorio": true, "opcoes": ["Dólar à vista agora (preço médio)", "Spread normal da mesa", "Expectativa do mercado para o payroll", "Posição atual da mesa", "Limite de posição e stop diário da mesa", "Volatilidade maior que o normal, por causa do dado", "Fluxo frequente de um importador que compra dólar à tarde", "Preço do petróleo"]}, {"id": "info_2", "tipo": "opcao", "rotulo": "Segunda informação mais importante (diferente da primeira)", "obrigatorio": true, "opcoes": ["Dólar à vista agora (preço médio)", "Spread normal da mesa", "Expectativa do mercado para o payroll", "Posição atual da mesa", "Limite de posição e stop diário da mesa", "Volatilidade maior que o normal, por causa do dado", "Fluxo frequente de um importador que compra dólar à tarde", "Preço do petróleo"]}, {"id": "info_3", "tipo": "opcao", "rotulo": "Terceira informação mais importante (diferente das anteriores)", "obrigatorio": true, "opcoes": ["Dólar à vista agora (preço médio)", "Spread normal da mesa", "Expectativa do mercado para o payroll", "Posição atual da mesa", "Limite de posição e stop diário da mesa", "Volatilidade maior que o normal, por causa do dado", "Fluxo frequente de um importador que compra dólar à tarde", "Preço do petróleo"]}]$$::jsonb,
  $${"titulo": "Informações disponíveis (cards que você pode abrir)", "colunas": ["Valor"], "linhas": [{"rotulo": "Dólar à vista agora (preço médio)", "celulas": [{"texto": "R$ 5,40", "valor": 5.4}]}, {"rotulo": "Spread normal da mesa", "celulas": [{"texto": "R$ 0,003 de cada lado", "valor": 0.003}]}, {"rotulo": "Expectativa do mercado para o payroll", "celulas": [{"texto": "150 mil novas vagas", "valor": 150}]}, {"rotulo": "Posição atual da mesa", "celulas": [{"texto": "Comprada em US$ 3 milhões", "valor": 3}]}, {"rotulo": "Limite de posição da mesa", "celulas": [{"texto": "US$ 10 milhões", "valor": 10}]}, {"rotulo": "Stop diário (perda máxima no dia)", "celulas": [{"texto": "R$ 300 mil", "valor": 300}]}, {"rotulo": "Volatilidade", "celulas": [{"texto": "Maior que o normal, por causa do dado"}]}, {"rotulo": "Um importador costuma comprar dólar à tarde", "celulas": [{"texto": "Fluxo frequente, mas não garantido"}]}, {"rotulo": "Preço do petróleo", "celulas": [{"texto": "Estável no dia"}]}]}$$::jsonb,
  $${"referencias": {"informacoes": ["Posição atual da mesa", "Limite de posição e stop diário da mesa", "Volatilidade maior que o normal, por causa do dado"]}, "distracao": "Preço do petróleo (estável no dia).", "leituraEsperada": "Posição atual, stop e limite, e a volatilidade antes do dado. O petróleo estável é a distração.", "observacao": "No PDF, 'stop e limite' contam como uma única informação; o stop e o limite aparecem em linhas separadas na tabela e foram agrupados nas opções.", "feedback": {"tres": "Você foi direto ao risco: a posição que a mesa já tem, até onde ela pode ir (limite e stop) e a volatilidade antes do dado.", "parcial": "Você identificou parte do que importa. Antes de cotar, a pergunta central é quanto risco a mesa já carrega e quanto ainda aguenta, e esse risco aumenta com a volatilidade.", "petroleo": "O petróleo estável é a distração: não muda o risco da mesa neste momento.", "nenhum": "Antes de cotar, olhe o risco da mesa: posição atual, limite e stop, e a volatilidade antes do dado."}, "rubrica": {"criterio": "Leitura do cenário (capítulo 1)", "escala": "1 a 4", "mostra": "Identificar posição atual, stop e limite, e volatilidade; descartar o petróleo."}}$$::jsonb),
($$st-task-cotacao$$, 'st-simplificado', $$st-cp-4$$, $$A cotação$$,
  $$Marina: “Quanto você paga pelos dólares dele?”
[[continuar]]
[[campos: preco, justificativa]]
O dólar à vista está em R$ 5,40 (preço médio) e o spread normal da mesa é R$ 0,003 de cada lado. Escolha o preço de compra (bid) que você cotaria ao cliente e justifique em uma frase.$$,
  $$[{"id": "preco", "tipo": "opcao", "rotulo": "Preço de compra (bid) que você cota ao cliente", "obrigatorio": true, "opcoes": ["R$ 5,397 (spread normal)", "R$ 5,392 (spread maior, pela volatilidade)", "R$ 5,380 (spread bem maior)"]}, {"id": "justificativa", "tipo": "texto", "rotulo": "Justifique em uma frase.", "obrigatorio": true, "limiteCaracteres": 240}]$$::jsonb,
  $${"titulo": "Cotação de referência", "colunas": ["Valor"], "linhas": [{"rotulo": "Dólar à vista (preço médio)", "celulas": [{"texto": "R$ 5,40", "valor": 5.4}]}, {"rotulo": "Spread normal da mesa", "celulas": [{"texto": "R$ 0,003 de cada lado", "valor": 0.003}]}, {"rotulo": "Tamanho da operação", "celulas": [{"texto": "US$ 5 milhões", "valor": 5}]}]}$$::jsonb,
  $${"referencias": {"preco": "R$ 5,392 (spread maior, pela volatilidade)"}, "leituraEsperada": "R$ 5,392 é o equilíbrio: o risco é maior antes do dado, mas o cliente precisa de um preço justo. R$ 5,380 tende a perder o cliente; R$ 5,397 não paga o risco extra.", "ganhoSpread": {"R$ 5,397": "0,003 x 5 milhões = R$ 15 mil (conta de conferência)", "R$ 5,392": "R$ 0,008 x 5 milhões = cerca de R$ 40 mil (valor do PDF)", "R$ 5,380": "0,020 x 5 milhões = R$ 100 mil (conta de conferência)"}, "feedback": {"5,392": "Boa! O spread cobre o risco maior antes do dado e ainda dá ao cliente um preço justo. A mesa ganha cerca de R$ 40 mil em spread (R$ 0,008 x 5 milhões).", "5,397": "É o spread normal, mas hoje o risco é maior por causa da volatilidade. Esse preço não paga o risco extra.", "5,380": "O spread bem maior protege a mesa, mas tende a perder o cliente: ele precisa de um preço justo."}, "criterioJustificativa": "Conectar o spread à volatilidade e à relação com o cliente.", "rubrica": {"criterio": "Precificação (capítulo 2)", "escala": "1 a 4", "mostra": "Spread coerente com o risco e com a relação com o cliente."}}$$::jsonb),
($$st-task-risco$$, 'st-simplificado', $$st-cp-5$$, $$O risco antes do dado$$,
  $$O cliente fecha a operação: a mesa compra os US$ 5 milhões dele.
Marina: “Agora estamos comprados em US$ 8 milhões e o payroll sai em minutos. O que você faz?”
[[continuar]]
Antes de decidir, calcule o que cada tamanho de posição perderia se o dólar caísse 1% (R$ 0,054). O limite de posição da mesa é de US$ 10 milhões e o stop diário é de R$ 300 mil.
[[continuar]]
[[campos: perda_8, perda_5, perda_3, posicao_maxima, decisao, justificativa]]
Use a perda por milhão de dólares comprado para calcular cada caso. Depois decida o que fazer antes do dado.$$,
  $$[{"id": "perda_8", "tipo": "numerico", "rotulo": "Perda com a posição de US$ 8 milhões se o dólar cair 1% (R$ 0,054)", "obrigatorio": true, "unidade": "R$ mil", "dica": "Eva: “Se o dólar cair R$ 0,054, quanto você perde para cada milhão de dólares comprado?”"}, {"id": "perda_5", "tipo": "numerico", "rotulo": "Perda com a posição de US$ 5 milhões se o dólar cair 1%", "obrigatorio": true, "unidade": "R$ mil", "dica": "Use vírgula como separador decimal."}, {"id": "perda_3", "tipo": "numerico", "rotulo": "Perda com a posição de US$ 3 milhões se o dólar cair 1%", "obrigatorio": true, "unidade": "R$ mil", "dica": "Use vírgula como separador decimal."}, {"id": "posicao_maxima", "tipo": "numerico", "rotulo": "Posição máxima para respeitar o stop num movimento de 1%", "obrigatorio": true, "unidade": "US$ milhões", "dica": "Use vírgula como separador decimal."}, {"id": "decisao", "tipo": "opcao", "rotulo": "O que você faz antes do dado?", "obrigatorio": true, "opcoes": ["Manter os US$ 8 milhões", "Vender US$ 3 milhões no mercado (ficar com US$ 5 milhões)", "Vender US$ 5 milhões (ficar com US$ 3 milhões)", "Zerar tudo"]}, {"id": "justificativa", "tipo": "texto", "rotulo": "Explique em até duas frases por que escolheu esse tamanho de posição.", "obrigatorio": true, "limiteCaracteres": 320}]$$::jsonb,
  $${"titulo": "Dados do momento", "colunas": ["Valor"], "linhas": [{"rotulo": "Posição atual da mesa", "celulas": [{"texto": "Comprada em US$ 8 milhões", "valor": 8}]}, {"rotulo": "Limite de posição", "celulas": [{"texto": "US$ 10 milhões", "valor": 10}]}, {"rotulo": "Stop diário", "celulas": [{"texto": "R$ 300 mil", "valor": 300}]}, {"rotulo": "Queda de 1% do dólar (de R$ 5,40)", "celulas": [{"texto": "R$ 0,054", "valor": 0.054}]}]}$$::jsonb,
  $${"referencias": {"perda_8": 432, "perda_5": 270, "perda_3": 162, "posicao_maxima": 5.5, "tolerancia": 0.1, "unidadePerdas": "R$ mil"}, "passoAPasso": "Perda = posição x R$ 0,054. Com 8 milhões: R$ 432 mil; com 5 milhões: R$ 270 mil; com 3 milhões: R$ 162 mil; zerando: 0. Posição máxima = R$ 300 mil / R$ 0,054 = cerca de US$ 5,56 milhões (o PDF diz 'cerca de US$ 5,5 milhões').", "leituraEsperada": "Com US$ 8 milhões, uma queda de 1% custa R$ 432 mil, acima do stop de R$ 300 mil. Boas respostas: ficar com 5 ou com 3. Zerar tudo é defensável, mas pode custar caro na execução.", "decisao": {"boas": ["Vender US$ 3 milhões no mercado (ficar com US$ 5 milhões)", "Vender US$ 5 milhões (ficar com US$ 3 milhões)"], "defensavel": ["Zerar tudo"], "inadequada": ["Manter os US$ 8 milhões"]}, "feedback": {"manter": "Com US$ 8 milhões, uma queda de 1% custa R$ 432 mil, acima do stop de R$ 300 mil. Manter a posição não respeita o stop.", "reduzir": "Boa! Com essa posição, uma queda de 1% fica dentro do stop de R$ 300 mil.", "zerar": "É defensável, porque elimina o risco, mas pode custar caro na execução: vender tudo de uma vez em minutos pode mexer no preço."}, "dicaDaEva": "Se o dólar cair R$ 0,054, quanto você perde para cada milhão de dólares comprado? (R$ 54 mil por milhão.)", "rubrica": {"criterio": "Gestão de risco (capítulo 3)", "escala": "1 a 4", "mostra": "Dimensionar a posição pelo stop."}}$$::jsonb),
($$st-task-reviravolta$$, 'st-simplificado', $$st-cp-6$$, $$A reviravolta: o payroll e o importador$$,
  $$Alerta: “Payroll: 300 mil vagas, o dobro do esperado. O dólar sobe 1,5%, para R$ 5,481.”
[[continuar]]
[[campos: posicao, resultado]]
O dólar foi de R$ 5,40 para R$ 5,481, uma alta de R$ 0,081. Informe qual posição você levou para o dado e calcule o resultado dela (posição x R$ 0,081).
[[continuar]]
[[campos: processo]]
Marina: “Quem mantiver uma posição maior ganhou mais hoje. Isso torna a decisão dela a melhor?”
[[continuar]]
Segundo alerta: o importador liga.
Importador: “Fiquei sabendo que uma exportadora vendeu dólar com vocês de manhã. Quanto foi? Preciso decidir se compro agora.”
[[continuar]]
[[campos: sigilo, sigilo_porque]]
Escolha como você responde ao importador e explique em uma frase.$$,
  $$[{"id": "posicao", "tipo": "opcao", "rotulo": "Qual posição você levou para o dado?", "obrigatorio": true, "opcoes": ["Manter os US$ 8 milhões", "Vender US$ 3 milhões no mercado (ficar com US$ 5 milhões)", "Vender US$ 5 milhões (ficar com US$ 3 milhões)", "Zerar tudo"]}, {"id": "resultado", "tipo": "numerico", "rotulo": "Resultado da sua posição depois da alta do dólar (positivo para ganho)", "obrigatorio": true, "unidade": "R$ mil", "dica": "Use vírgula como separador decimal."}, {"id": "processo", "tipo": "opcao", "rotulo": "Ter ganhado mais mantendo uma posição maior torna essa decisão a melhor?", "obrigatorio": true, "opcoes": ["Sim: quem ganha mais acertou.", "Não: a avaliação olha o processo (respeitar o stop), não a sorte."]}, {"id": "sigilo", "tipo": "opcao", "rotulo": "Como você responde ao importador?", "obrigatorio": true, "opcoes": ["Conto quanto foi.", "Dou uma pista, sem dizer o valor.", "Não informo, porque a operação de um cliente é sigilosa."]}, {"id": "sigilo_porque", "tipo": "texto", "rotulo": "Explique sua resposta em uma frase.", "obrigatorio": true, "limiteCaracteres": 240}]$$::jsonb,
  $${"titulo": "Movimento do dólar depois do payroll", "colunas": ["Antes", "Depois"], "linhas": [{"rotulo": "Dólar à vista", "celulas": [{"texto": "R$ 5,40", "valor": 5.4}, {"texto": "R$ 5,481", "valor": 5.481}]}, {"rotulo": "Variação", "celulas": [{"texto": "-"}, {"texto": "+1,5% (R$ 0,081)", "valor": 0.081}]}]}$$::jsonb,
  $${"referencias": {"resultadoPorPosicao": {"Manter os US$ 8 milhões": 648, "Vender US$ 3 milhões no mercado (ficar com US$ 5 milhões)": 405, "Vender US$ 5 milhões (ficar com US$ 3 milhões)": 243, "Zerar tudo": 0}, "unidade": "R$ mil", "tolerancia": 1, "processo": "Não: a avaliação olha o processo (respeitar o stop), não a sorte.", "sigilo": "Não informo, porque a operação de um cliente é sigilosa."}, "passoAPasso": "Ganho = posição x R$ 0,081. Com 8 milhões: R$ 648 mil; com 5 milhões: R$ 405 mil; com 3 milhões: R$ 243 mil; zerando tudo: 0. Conferência: 5,40 x 1,015 = 5,481.", "leituraEsperada": "Ter ganhado mais mantendo a posição não torna a decisão certa; a avaliação olha o processo (respeitar o stop), não a sorte. Na ética, só vale não informar.", "observacao": "Quem escolheu manter US$ 8 milhões ganhou R$ 648 mil, mas desrespeitou o stop num cenário de queda de 1% (perda de R$ 432 mil). O resultado não corrige o processo. Contar a operação de um cliente zera o critério 4 da rubrica.", "feedback": {"nao_informar": "Isso! A operação de um cliente é sigilosa: informar, ou dar pista, quebra a confiança e é conduta inadequada.", "contar_ou_pista": "Contar ou insinuar a operação de outro cliente quebra o sigilo, que é regra da mesa. A única resposta possível é não informar.", "processo_certo": "Isso: o resultado do dia depende em parte da sorte; o processo de respeitar o stop é o que se avalia.", "processo_errado": "Ganhar mais mantendo a posição não torna a decisão certa: se o dado viesse ao contrário, a perda passaria do stop."}, "rubrica": {"criterio": "Adaptação e ética (capítulo 4)", "escala": "1 a 4", "mostra": "Calcular o resultado, separar processo de sorte e proteger o sigilo do cliente. Contar a operação de um cliente zera este critério."}}$$::jsonb),
($$st-task-banca$$, 'st-simplificado', $$st-cp-7$$, $$A banca$$,
  $$A banca da mesa avalia suas decisões do dia: Ricardo, Paula e Helena.
[[continuar]]
[[campos: ricardo]]
Ricardo: “Em uma frase: por que você reduziu (ou não) a posição antes do dado?”
[[continuar]]
[[campos: paula]]
Paula: “E se o dado tivesse vindo fraco e o dólar caído 2%?”
[[continuar]]
[[campos: helena]]
Helena: “Como você explica para a exportadora o preço que cobrou?”$$,
  $$[{"id": "ricardo", "tipo": "texto", "rotulo": "Resposta a Ricardo (uma frase)", "obrigatorio": true, "limiteCaracteres": 280}, {"id": "paula", "tipo": "texto", "rotulo": "Resposta a Paula (até 60 palavras)", "obrigatorio": true, "limiteCaracteres": 420}, {"id": "helena", "tipo": "texto", "rotulo": "Resposta a Helena (até 80 palavras)", "obrigatorio": true, "limiteCaracteres": 560}]$$::jsonb,
  NULL,
  $${"banca": [{"quem": "Ricardo", "pergunta": "Em uma frase: por que você reduziu (ou não) a posição antes do dado?", "mostra": "Clareza e lógica de risco"}, {"quem": "Paula", "pergunta": "E se o dado tivesse vindo fraco e o dólar caído 2%?", "mostra": "Pensar em cenários, não só no que aconteceu"}, {"quem": "Helena", "pergunta": "Como você explica para a exportadora o preço que cobrou?", "mostra": "Transparência e relação de longo prazo com o cliente"}], "referenciasParaCorrecao": {"ricardo": "Ligar o tamanho da posição ao stop de R$ 300 mil: com US$ 8 milhões uma queda de 1% custa R$ 432 mil.", "paula": "Uma queda de 2% (R$ 0,108) custaria R$ 864 mil com US$ 8 milhões, R$ 540 mil com 5, R$ 324 mil com 3 (contas de conferência). Mesmo com a posição reduzida, 2% ultrapassa o stop; mostrar plano para esse cenário (reduzir mais, tamanho menor).", "helena": "Explicar o spread pela volatilidade antes do dado e pela necessidade de dar um preço justo ao cliente, com transparência e olhando a relação de longo prazo."}, "rubrica": [{"n": 1, "criterio": "Leitura do cenário", "capitulo": 1}, {"n": 2, "criterio": "Precificação: spread coerente com o risco e com a relação com o cliente", "capitulo": 2}, {"n": 3, "criterio": "Gestão de risco: dimensiona a posição pelo stop", "capitulo": 3}, {"n": 4, "criterio": "Adaptação e ética: calcula o resultado, separa processo de sorte e protege o sigilo do cliente (contar a operação de um cliente zera este critério)", "capitulo": 4}, {"n": 5, "criterio": "Comunicação", "capitulo": 5}], "escala": "Cada critério de 1 a 4. O PDF não traz descritores por nível."}$$::jsonb),
($$st-ctask-risco$$, 'st-complexo', $$st-cpc-3$$, $$Risco atual do livro$$,
  $$Você trabalha como estagiária na mesa de renda fixa da Arquipélago. O trader responsável pelo livro de títulos prefixados saiu de férias e a head da mesa pediu sua ajuda: o livro está acima do limite de risco, o Copom decide amanhã e um cliente quer negociar. Sua missão é medir o risco do livro, montar o hedge, testar cenários e recomendar o que fazer.

Valores fictícios. Considere aproximações lineares (sem convexidade, sem carregamento e sem custos de corretagem).

O livro está comprado em títulos prefixados: ganha se as taxas caem e perde se sobem. Os DV01 estão na tabela de dados.

Limites da mesa: DV01 máximo do livro de R$ 12.000; stop diário (perda máxima) de R$ 400 mil; perda máxima no mês de R$ 1,5 milhão, dos quais R$ 600 mil já foram usados.

Tarefa 1. Explique, em palavras simples, por que o livro perde quando a taxa sobe. Calcule a perda com uma alta paralela de 0,25 ponto e diga se ela respeita o stop diário.

Entregável desta parte: aba 1 da planilha, risco do livro.$$,
  $$[{"id": "explicacao", "tipo": "texto", "rotulo": "Explique, em palavras simples, por que o livro perde quando a taxa sobe.", "obrigatorio": true, "limiteCaracteres": 600}, {"id": "perda_025", "tipo": "numerico", "rotulo": "Perda do livro com alta paralela de 0,25 ponto (25 bps)", "obrigatorio": true, "unidade": "R$ mil", "dica": "Use vírgula como separador decimal."}, {"id": "respeita_stop", "tipo": "opcao", "rotulo": "A perda respeita o stop diário de R$ 400 mil?", "obrigatorio": true, "opcoes": ["Sim, respeita o stop", "Não, fica acima do stop"]}]$$::jsonb,
  $${"titulo": "O livro hoje", "colunas": ["Valor de mercado (R$ milhões)", "Taxa atual", "DV01 (R$ por 0,01 ponto percentual)"], "linhas": [{"rotulo": "LTN jan/2028", "celulas": [{"texto": "30", "valor": 30}, {"texto": "13,60%", "valor": 13.6}, {"texto": "9.000", "valor": 9000}]}, {"rotulo": "LTN jan/2030", "celulas": [{"texto": "20", "valor": 20}, {"texto": "13,80%", "valor": 13.8}, {"texto": "11.000", "valor": 11000}]}, {"rotulo": "Total", "celulas": [{"texto": "50", "valor": 50}, {"texto": "-"}, {"texto": "20.000", "valor": 20000}]}]}$$::jsonb,
  $${"referencias": {"perda_025": 500, "unidade": "R$ mil", "tolerancia": 1, "respeita_stop": "Não, fica acima do stop"}, "passoAPasso": "Perda = DV01 total x variação em bps = 20.000 x 25 = R$ 500 mil, acima do stop diário de R$ 400 mil. O DV01 de R$ 20.000 também está acima do limite de R$ 12.000.", "observacao": "Do limite mensal de R$ 1,5 milhão, restam R$ 900 mil (R$ 1,5 milhão - R$ 600 mil já usados), valor que não é perguntado.", "avaliacao": "A explicação deve dizer que o livro está comprado em prefixados: quando a taxa de mercado sobe, o fluxo fixo vale menos hoje e o preço cai. Aceitar menção ao DV01 como medida da sensibilidade."}$$::jsonb),
($$st-ctask-hedge$$, 'st-complexo', $$st-cpc-4$$, $$Hedge para o limite$$,
  $$Para se proteger da alta de juros, a mesa precisa ficar tomada em taxa no DI futuro (ganha quando a taxa sobe). Os contratos disponíveis são o DI1 jan/2028, com DV01 de R$ 13,50 por contrato, e o DI1 jan/2030, com DV01 de R$ 21,00 por contrato.

Tarefa 2. Calcule quantos contratos de DI futuro são necessários para trazer o DV01 do livro para R$ 12.000. Compare duas formas: (a) tudo no jan/2030; (b) dividido entre os dois vencimentos, proporcional ao risco de cada título.

Entregável desta parte: aba 2 da planilha, hedge (contratos por forma).$$,
  $$[{"id": "reducao_dv01", "tipo": "numerico", "rotulo": "DV01 a reduzir para chegar ao limite", "obrigatorio": true, "unidade": "R$", "dica": "Informe o valor em reais, sem separador de milhar."}, {"id": "contratos_2030", "tipo": "numerico", "rotulo": "Forma (a): contratos de DI1 jan/2030 tomados", "obrigatorio": true, "unidade": "contratos", "dica": "Arredonde para o inteiro mais próximo."}, {"id": "contratos_2028_prop", "tipo": "numerico", "rotulo": "Forma (b): contratos de DI1 jan/2028 tomados", "obrigatorio": true, "unidade": "contratos", "dica": "Arredonde para o inteiro mais próximo."}, {"id": "contratos_2030_prop", "tipo": "numerico", "rotulo": "Forma (b): contratos de DI1 jan/2030 tomados", "obrigatorio": true, "unidade": "contratos", "dica": "Arredonde para o inteiro mais próximo."}, {"id": "comparacao", "tipo": "texto", "rotulo": "Em uma ou duas frases: o que muda entre as duas formas no risco que sobra em cada vencimento?", "obrigatorio": true, "limiteCaracteres": 500}]$$::jsonb,
  $${"titulo": "Livro e contratos de DI futuro", "colunas": ["DV01 do livro (R$)", "DV01 por contrato de DI1 (R$)"], "linhas": [{"rotulo": "jan/2028", "celulas": [{"texto": "9.000", "valor": 9000}, {"texto": "13,50", "valor": 13.5}]}, {"rotulo": "jan/2030", "celulas": [{"texto": "11.000", "valor": 11000}, {"texto": "21,00", "valor": 21.0}]}, {"rotulo": "Total do livro", "celulas": [{"texto": "20.000", "valor": 20000}, {"texto": "-"}]}, {"rotulo": "DV01 máximo do livro", "celulas": [{"texto": "12.000", "valor": 12000}, {"texto": "-"}]}]}$$::jsonb,
  $${"referencias": {"reducao_dv01": 8000, "contratos_2030": 381, "contratos_2028_prop": 267, "contratos_2030_prop": 210, "tolerancia_contratos": 2}, "passoAPasso": "DV01 a reduzir = 20.000 - 12.000 = R$ 8.000. (a) Tudo no jan/2030: 8.000 / 21 = 380,95, cerca de 381 contratos. (b) Proporcional ao risco de cada título (9.000 : 11.000): R$ 3.600 no jan/2028 = 3.600 / 13,5 = 266,7, cerca de 267 contratos; R$ 4.400 no jan/2030 = 4.400 / 21 = 209,5, cerca de 210 contratos. DV01 que sobra: (a) R$ 9.000 no jan/2028 e R$ 3.000 no jan/2030; (b) R$ 5.400 no jan/2028 e R$ 6.600 no jan/2030. Total em ambos: R$ 12.000.", "avaliacao": "Aceitar variação de até 2 contratos por arredondamento."}$$::jsonb),
($$st-ctask-cenarios$$, 'st-complexo', $$st-cpc-5$$, $$Cenários do Copom$$,
  $$O mercado está dividido entre manutenção e alta de 0,25 ponto da Selic. Os economistas da casa veem três cenários para as taxas: A, alta paralela (todas sobem 0,50 ponto); B, inclinação (as curtas sobem 0,10 ponto e as longas, 0,40); C, achatamento (as curtas sobem 0,40 ponto e as longas, 0,10).

Tarefa 3. Calcule o resultado do livro nos cenários A, B e C, sem hedge e com as duas formas de hedge da tarefa anterior: (a) só no jan/2030 e (b) proporcional ao risco de cada título. Use o DV01 que sobra em cada vencimento depois do hedge. Qual forma protege melhor? Por quê?

Entregável desta parte: aba 3 da planilha, cenários (sem e com hedge).$$,
  $$[{"id": "a_sem", "tipo": "numerico", "rotulo": "Cenário A (alta paralela): resultado sem hedge", "obrigatorio": true, "unidade": "R$ mil", "dica": "Use vírgula como separador decimal e sinal negativo para perda."}, {"id": "a_2030", "tipo": "numerico", "rotulo": "Cenário A (alta paralela): resultado com hedge só no jan/2030", "obrigatorio": true, "unidade": "R$ mil", "dica": "Use sinal negativo para perda."}, {"id": "a_prop", "tipo": "numerico", "rotulo": "Cenário A (alta paralela): resultado com hedge proporcional", "obrigatorio": true, "unidade": "R$ mil", "dica": "Use sinal negativo para perda."}, {"id": "b_sem", "tipo": "numerico", "rotulo": "Cenário B (inclinação): resultado sem hedge", "obrigatorio": true, "unidade": "R$ mil", "dica": "Use vírgula como separador decimal e sinal negativo para perda."}, {"id": "b_2030", "tipo": "numerico", "rotulo": "Cenário B (inclinação): resultado com hedge só no jan/2030", "obrigatorio": true, "unidade": "R$ mil", "dica": "Use sinal negativo para perda."}, {"id": "b_prop", "tipo": "numerico", "rotulo": "Cenário B (inclinação): resultado com hedge proporcional", "obrigatorio": true, "unidade": "R$ mil", "dica": "Use sinal negativo para perda."}, {"id": "c_sem", "tipo": "numerico", "rotulo": "Cenário C (achatamento): resultado sem hedge", "obrigatorio": true, "unidade": "R$ mil", "dica": "Use vírgula como separador decimal e sinal negativo para perda."}, {"id": "c_2030", "tipo": "numerico", "rotulo": "Cenário C (achatamento): resultado com hedge só no jan/2030", "obrigatorio": true, "unidade": "R$ mil", "dica": "Use sinal negativo para perda."}, {"id": "c_prop", "tipo": "numerico", "rotulo": "Cenário C (achatamento): resultado com hedge proporcional", "obrigatorio": true, "unidade": "R$ mil", "dica": "Use sinal negativo para perda."}, {"id": "melhor_forma", "tipo": "opcao", "rotulo": "Qual forma de hedge protege melhor, olhando os três cenários?", "obrigatorio": true, "opcoes": ["Tudo no jan/2030", "Proporcional ao risco de cada título", "As duas são iguais em todos os cenários"]}, {"id": "porque", "tipo": "texto", "rotulo": "Por quê? Explique em poucas frases.", "obrigatorio": true, "limiteCaracteres": 600}]$$::jsonb,
  $${"titulo": "Cenários para amanhã (variação das taxas, em pontos-base)", "colunas": ["Taxas curtas (jan/2028)", "Taxas longas (jan/2030)"], "linhas": [{"rotulo": "A. Alta paralela", "celulas": [{"texto": "+50 bps", "valor": 50}, {"texto": "+50 bps", "valor": 50}]}, {"rotulo": "B. Inclinação", "celulas": [{"texto": "+10 bps", "valor": 10}, {"texto": "+40 bps", "valor": 40}]}, {"rotulo": "C. Achatamento", "celulas": [{"texto": "+40 bps", "valor": 40}, {"texto": "+10 bps", "valor": 10}]}]}$$::jsonb,
  $${"referencias": {"a_sem": -1000, "a_2030": -600, "a_prop": -600, "b_sem": -530, "b_2030": -210, "b_prop": -320, "c_sem": -470, "c_2030": -390, "c_prop": -280, "unidade": "R$ mil", "tolerancia": 10, "melhor_forma": "Proporcional ao risco de cada título"}, "passoAPasso": "Resultado = soma(DV01 que sobra x bps). Sem hedge: DV01 9.000 (2028) e 11.000 (2030). (a) Só jan/2030: sobram 9.000 e 3.000. (b) Proporcional: sobram 5.400 e 6.600. A: -1.000 sem hedge; -600 nas duas formas (DV01 de 12.000 x 50). B: -9.000x10 - 11.000x40 = -530; (a) -9.000x10 - 3.000x40 = -210; (b) -5.400x10 - 6.600x40 = -318, que o PDF arredonda para cerca de -320. C: -9.000x40 - 11.000x10 = -470; (a) -9.000x40 - 3.000x10 = -390; (b) -5.400x40 - 6.600x10 = -282, cerca de -280 no PDF.", "conclusao": "Proteger cada vencimento onde está o risco funciona melhor em cenários incertos.", "nuance": "O hedge só no jan/2030 é melhor no cenário B (-210 contra -320), mas pior no C (-390 contra -280). O pior resultado entre B e C é -390 no hedge só no 2030 e -320 no proporcional; por isso o proporcional é mais robusto quando não se sabe qual cenário ocorrerá. No cenário A as duas formas são iguais, e nenhuma respeita o stop.", "avaliacao": "Aceitar a escolha do proporcional com a justificativa de robustez a cenários incertos e a menção de que o hedge só no 2030 deixa o risco do jan/2028 sem proteção. Uma resposta que cite que a forma (a) ganha no cenário B e perde no C também é válida."}$$::jsonb),
($$st-ctask-stop$$, 'st-complexo', $$st-cpc-6$$, $$O stop e o hedge$$,
  $$Tarefa 4. Com o hedge que traz o DV01 para R$ 12.000, o cenário A (alta paralela de 0,50 ponto) respeita o stop diário de R$ 400 mil? Se não, qual DV01 máximo seria necessário e quantos contratos a mais de DI1 jan/2030 seriam precisos, além dos da tarefa 2 (forma a)?$$,
  $$[{"id": "respeita", "tipo": "opcao", "rotulo": "Com DV01 de R$ 12.000, o cenário A respeita o stop?", "obrigatorio": true, "opcoes": ["Sim, respeita o stop", "Não, fica acima do stop"]}, {"id": "dv01_maximo", "tipo": "numerico", "rotulo": "DV01 máximo para respeitar o stop no cenário A", "obrigatorio": true, "unidade": "R$", "dica": "Informe o valor em reais, sem separador de milhar."}, {"id": "contratos_extra", "tipo": "numerico", "rotulo": "Contratos adicionais de DI1 jan/2030, além dos 381 da tarefa 2", "obrigatorio": true, "unidade": "contratos", "dica": "Arredonde para o inteiro mais próximo."}, {"id": "comentario", "tipo": "texto", "rotulo": "Em uma ou duas frases: o que essa conta mostra sobre o limite de DV01 e o stop?", "obrigatorio": true, "limiteCaracteres": 450}]$$::jsonb,
  $${"titulo": "Stop e cenário A", "colunas": ["Valor"], "linhas": [{"rotulo": "Stop diário", "celulas": [{"texto": "R$ 400 mil", "valor": 400}]}, {"rotulo": "Cenário A", "celulas": [{"texto": "Alta paralela de 50 bps", "valor": 50}]}, {"rotulo": "DV01 do livro com hedge para o limite", "celulas": [{"texto": "R$ 12.000", "valor": 12000}]}, {"rotulo": "DV01 por contrato de DI1 jan/2030", "celulas": [{"texto": "R$ 21,00", "valor": 21.0}]}, {"rotulo": "Contratos jan/2030 do hedge para o limite", "celulas": [{"texto": "381 (forma a)", "valor": 381}]}]}$$::jsonb,
  $${"referencias": {"respeita": "Não, fica acima do stop", "dv01_maximo": 8000, "contratos_extra": 190, "contratos_total_2030": 571, "tolerancia_contratos": 2}, "passoAPasso": "Com DV01 de R$ 12.000 e alta de 50 bps, a perda é R$ 600 mil, acima do stop de R$ 400 mil. DV01 máximo = 400.000 / 50 = R$ 8.000, ou seja, reduzir mais R$ 4.000. Contratos: 4.000 / 21 = 190,5, cerca de 190 a mais, ou cerca de 571 contratos jan/2030 no total (12.000 / 21 = 571,4).", "observacao": "No PDF, 'hedge de R$ 12.000 (por exemplo, cerca de 571 contratos jan/2030)' significa reduzir R$ 12.000 de DV01 (de 20.000 para 8.000). O PDF não dá o número de contratos adicionais explicitamente; 190 é 571 - 381. O limite de DV01 da mesa (R$ 12.000) pode, portanto, não bastar para respeitar o stop.", "avaliacao": "Aceitar de 190 a 191 contratos adicionais (4.000 / 21 = 190,5), ou 571 a 572 no total."}$$::jsonb),
($$st-ctask-cliente$$, 'st-complexo', $$st-cpc-7$$, $$Fluxo do cliente$$,
  $$Um fundo quer comprar R$ 10 milhões de LTN jan/2030 da mesa. A taxa média de mercado é 13,80%.

Tarefa 5. Proponha a taxa de venda ao cliente, calcule o ganho de spread e explique como essa venda ajuda o risco do livro. Lembre que, quando a mesa vende um título, uma taxa menor significa um preço maior para o cliente.

Entregável desta parte: aba 4 da planilha, fluxo do cliente.$$,
  $$[{"id": "taxa_venda", "tipo": "numerico", "rotulo": "Taxa de venda ao cliente (ao ano)", "obrigatorio": true, "unidade": "% a.a.", "dica": "Use vírgula como separador decimal. Ex.: 13,25"}, {"id": "dv01_vendido", "tipo": "numerico", "rotulo": "DV01 que o livro vende nesta operação", "obrigatorio": true, "unidade": "R$", "dica": "Informe o valor em reais, sem separador de milhar."}, {"id": "ganho_spread", "tipo": "numerico", "rotulo": "Ganho de spread da mesa com a taxa que você propôs", "obrigatorio": true, "unidade": "R$", "dica": "Informe o valor em reais, sem separador de milhar."}, {"id": "explicacao", "tipo": "texto", "rotulo": "Explique como essa venda ajuda o risco do livro e por que a taxa proposta é razoável.", "obrigatorio": true, "limiteCaracteres": 700}]$$::jsonb,
  $${"titulo": "Fluxo do cliente", "colunas": ["Valor"], "linhas": [{"rotulo": "Cliente", "celulas": [{"texto": "Fundo"}]}, {"rotulo": "Operação", "celulas": [{"texto": "Compra R$ 10 milhões de LTN jan/2030 da mesa", "valor": 10}]}, {"rotulo": "Taxa média de mercado do jan/2030", "celulas": [{"texto": "13,80%", "valor": 13.8}]}, {"rotulo": "DV01 do jan/2030 no livro (R$ 20 milhões)", "celulas": [{"texto": "R$ 11.000", "valor": 11000}]}]}$$::jsonb,
  $${"referencias": {"taxa_venda": 13.78, "dv01_vendido": 5500, "ganho_spread": 11000, "unidade_ganho": "R$", "tolerancia_taxa_pontos": 0.05}, "passoAPasso": "DV01 do jan/2030 por R$ 1 milhão = 11.000 / 20 = R$ 550; para R$ 10 milhões, R$ 5.500. Vender a 13,78% (2 bps abaixo da média de 13,80%, preço um pouco acima do mercado) dá spread de 2 x 5.500 = R$ 11.000 e reduz o DV01 do livro em R$ 5.500, um hedge natural.", "observacao": "Qualquer taxa de venda um pouco abaixo de 13,80% é defensável; o ganho de spread é (13,80 - taxa em %) x 100 x R$ 5.500. O PDF usa 13,78%. O DV01 total do livro cai de R$ 20.000 para R$ 14.500 com essa venda.", "avaliacao": "Verificar coerência entre a taxa proposta, o spread e a explicação: a mesa vende risco que já tinha, reduzindo o DV01 do livro sem usar o DI futuro."}$$::jsonb),
($$st-ctask-conduta$$, 'st-complexo', $$st-cpc-8$$, $$Conduta com clientes$$,
  $$Tarefa 6. Outro cliente pergunta: “Quem está vendendo jan/2030 hoje?”

O que você responde e por quê?$$,
  $$[{"id": "postura", "tipo": "opcao", "rotulo": "Como você responde?", "obrigatorio": true, "opcoes": ["Conto quem está vendendo.", "Dou uma pista, sem dizer o nome.", "Não revelo operações de outros clientes."]}, {"id": "resposta", "tipo": "texto", "rotulo": "Escreva a resposta que daria ao cliente e explique por quê.", "obrigatorio": true, "limiteCaracteres": 600}]$$::jsonb,
  NULL,
  $${"referencias": {"postura": "Não revelo operações de outros clientes."}, "avaliacao": "Não revelar operações de outros clientes: o sigilo é regra da mesa e de compliance. A resposta pode oferecer ajuda alternativa (por exemplo, cotar o título que o cliente quer), sem insinuar nada. Revelar nome ou dar pista é conduta inadequada."}$$::jsonb),
($$st-ctask-memorando$$, 'st-complexo', $$st-cpc-9$$, $$Memorando para a head da mesa$$,
  $$Escreva um memorando de uma página para a head da mesa, Marina: o que fazer antes do Copom, com números, e uma recomendação para o fluxo do cliente.

Use os resultados das tarefas anteriores: o DV01 atual e o limite, a perda de 0,25 ponto contra o stop, o número de contratos de cada forma de hedge, o resultado nos cenários A, B e C, o DV01 máximo que respeita o stop e o efeito da venda ao fundo. Diga qual hedge você faria e por que, e se aceitaria o fluxo na taxa que propôs.

Entregável: a planilha com as abas 1 (risco do livro), 2 (hedge), 3 (cenários) e 4 (fluxo do cliente), além do memorando.$$,
  $$[{"id": "memorando", "tipo": "texto", "rotulo": "Memorando de uma página para a head da mesa", "obrigatorio": true, "limiteCaracteres": 3000}, {"id": "recomendacao_fluxo", "tipo": "texto", "rotulo": "Recomendação para o fluxo do cliente (taxa, spread e efeito no risco)", "obrigatorio": true, "limiteCaracteres": 800}, {"id": "planilha", "tipo": "arquivo", "rotulo": "Anexar a planilha completa (opcional)", "obrigatorio": false, "dica": "PDF, XLSX ou CSV, até 10 MB"}]$$::jsonb,
  NULL,
  $${"referencias": {"dv01_atual": 20000, "limite_dv01": 12000, "perda_025": 500, "stop": 400, "hedge_2030": 381, "hedge_prop": {"jan2028": 267, "jan2030": 210}, "dv01_maximo_stop_A": 8000, "contratos_total_2030_para_stop": 571, "ganho_spread_cliente": 11, "dv01_vendido_cliente": 5500, "unidade": "R$ mil, exceto contratos e DV01"}, "avaliacao": "O memorando deve ter números corretos e uma ação clara antes do Copom: trazer o DV01 ao limite de R$ 12.000 (381 contratos jan/2030, ou 267 jan/2028 e 210 jan/2030) e discutir que, para respeitar o stop de R$ 400 mil no cenário A, o DV01 precisaria cair para R$ 8.000 (cerca de 571 contratos jan/2030 no total). Recomendar o hedge proporcional é coerente com os cenários B e C (pior resultado entre B e C de -320 contra -390), mas aceitar justificativa diferente se for numérica. O fluxo do cliente a 13,78% rende cerca de R$ 11 mil e reduz o DV01 em R$ 5.500, um hedge natural. Lembrar do limite mensal: R$ 900 mil restantes.", "perguntasDeDefesa": ["Por que essa forma de hedge e não a outra?", "O que acontece se a decisão do Copom for manutenção e o hedge tomado perder?", "O que você faria para respeitar o stop no cenário A?", "Por que não responder ao cliente sobre quem vende jan/2030?"], "observacao": "As perguntas de defesa são sugestões para quem corrige; o PDF não as traz."}$$::jsonb)
ON CONFLICT (id) DO NOTHING;
